#!/usr/bin/env php
<?php
declare(strict_types=1); require_once __DIR__.'/../includes/task_system_operations.php';
$o=getopt('',['json','strict']);$strict=isset($o['strict']);$checks=[];
$add=static function(string $id,bool $ok,string $detail,string $severity='failure')use(&$checks):void{$checks[]=['id'=>$id,'status'=>$ok?'pass':$severity,'detail'=>$detail];};
$add('php_version',version_compare(PHP_VERSION,'8.2.0','>='),PHP_MAJOR_VERSION.'.'.PHP_MINOR_VERSION);
foreach(['PDO'=>'PDO','pdo_sqlite'=>'PDO SQLite','sodium'=>'sodium','gd'=>'GD','json'=>'JSON','mbstring'=>'mbstring','openssl'=>'OpenSSL'] as $ext=>$label)$add('extension_'.$ext,extension_loaded($ext),$label);
$root=TaskSystemOperations::root();$dbPath=TaskSystemOperations::databasePath();$dir=dirname($dbPath);
$add('composer_lock',is_file($root.'/composer.lock'),'composer.lock');$add('composer_autoload',is_file($root.'/vendor/autoload.php'),'Composer production autoload');
$add('database_directory',is_dir($dir)&&is_readable($dir)&&is_writable($dir),'database directory '.(is_writable($dir)?'read/write':'not writable'));
$add('database_exists',is_file($dbPath),'database '.basename($dbPath));$add('disk_space',(int)@disk_free_space($dir)>100*1024*1024,'at least 100 MiB free');
if(is_file($dbPath)&&extension_loaded('pdo_sqlite'))try{$db=TaskSystemOperations::open($dbPath);$add('sqlite_version',version_compare((string)$db->query('SELECT sqlite_version()')->fetchColumn(),'3.27.0','>='),(string)$db->query('SELECT sqlite_version()')->fetchColumn());$add('foreign_keys',(int)$db->query('PRAGMA foreign_keys')->fetchColumn()===1,'enabled');$add('integrity',(string)$db->query('PRAGMA integrity_check')->fetchColumn()==='ok','integrity check');$versions=in_array('schema_migrations',TaskSystemOperations::tables($db),true)?$db->query('SELECT version FROM schema_migrations ORDER BY version')->fetchAll(PDO::FETCH_COLUMN):[];$add('schema_versions',$versions!==[],'versions: '.implode(',',$versions));}catch(Throwable $e){$add('database_open',false,'database could not be inspected');}
foreach(['data/tasks/tasks.json','storage/employee-users/employees.json','storage/push/subscriptions.json'] as $f)$add('legacy_'.str_replace(['/','.'],['_','_'],$f),!is_file($root.'/'.$f),basename($f).' absent or retained for migration','warning');
$icons=['assets/icons/employee/icon-192.png'=>[192,192],'assets/icons/employee/icon-512.png'=>[512,512]];foreach($icons as $f=>$dim){$size=is_file($root.'/'.$f)?@getimagesize($root.'/'.$f):false;$add('icon_'.$dim[0],is_array($size)&&$size[0]===$dim[0]&&$size[1]===$dim[1],$dim[0].'x'.$dim[1].' generated icon','warning');}
$push=filter_var(getenv('PUSH_ENABLED')?:'0',FILTER_VALIDATE_BOOL);$add('push_safe_default',!$push,'push disabled by default');$add('vapid_configuration',!$push||(getenv('WEB_PUSH_VAPID_PUBLIC_KEY')&&getenv('WEB_PUSH_VAPID_PRIVATE_KEY')&&getenv('WEB_PUSH_VAPID_SUBJECT')),'VAPID '.($push?'configured':'not required while disabled'));
$key=getenv('PUSH_SUBSCRIPTION_ENCRYPTION_KEY');$decoded=is_string($key)&&$key!==''?base64_decode($key,true):false;$add('push_encryption',!$push||(is_string($decoded)&&strlen($decoded)===32),'encryption key '.($push?'validated':'not required while disabled'));
foreach(['bin/generate-task-notifications.php','bin/send-task-push.php','bin/migrate-push-json.php','api/push-subscriptions.php','employee-manifest.webmanifest','service-worker.js','employee-app.php'] as $f)$add('file_'.strtr($f,['/'=>'_','.'=>'_']),is_file($root.'/'.$f),$f);
$add('backup_directory',is_dir($root.'/storage')&&is_writable($root.'/storage'),'backup parent writable');$add('demo_credentials',getenv('PORTAL_SEED_DEMO_USERS')!=='1','demo credential seeding disabled');
$fail=count(array_filter($checks,fn($c)=>$c['status']==='failure'));$warn=count(array_filter($checks,fn($c)=>$c['status']==='warning'));$report=['ok'=>$fail===0&&(!$strict||$warn===0),'strict'=>$strict,'summary'=>['pass'=>count($checks)-$fail-$warn,'warning'=>$warn,'failure'=>$fail],'checks'=>$checks];
if(isset($o['json']))echo json_encode($report,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES).PHP_EOL;else{foreach($checks as $c)printf("%-7s %-35s %s\n",strtoupper($c['status']),$c['id'],$c['detail']);printf("Summary: %d pass, %d warning, %d failure\n",$report['summary']['pass'],$warn,$fail);}exit($fail>0||($strict&&$warn>0)?2:0);
